insert into public.recipes (slug, title, description, storage_note, servings, prep_minutes,
  cook_minutes, tags, status, source, source_ref, validated_at)
select v.slug, v.title, v.description, v.storage, v.servings, v.prep, v.cook, v.tags,
  'published', 'curated', 'Marmy — recette originale', now()
from (values
  ('puree-minute-ail-steak-hache-haricots-verts', 'Purée minute à l''ail, steak haché et haricots verts', 'Une purée en flocons montée au lait et parfumée à l''ail, un bœuf haché saisi et des haricots verts surgelés. Le classique du soir pressé, en un quart d''heure.', 'À manger tout de suite ; la purée se réchauffe avec un trait de lait.', 2, 3, 12, array['plat', 'poele', 'flemme', 'express']::text[]),
  ('puree-verte-epinards-oeufs-mollets', 'Purée verte aux épinards et œufs mollets', 'Une purée minute dans laquelle on fond des épinards surgelés, servie avec des œufs mollets au jaune coulant. Doux, réconfortant, sans rien à éplucher.', 'À manger tout de suite.', 2, 2, 12, array['plat', 'flemme', 'express']::text[]),
  ('dinde-moutarde-petits-pois-carottes-puree', 'Dinde à la moutarde, petits pois-carottes et purée minute', 'Des escalopes de dinde dorées et nappées d''une sauce minute à la moutarde, avec des petits pois-carottes surgelés et une purée en flocons.', 'La dinde et les légumes se gardent 2 jours au réfrigérateur.', 2, 3, 12, array['plat', 'poele', 'flemme', 'express']::text[]),
  ('maquereau-moutarde-puree-carottes-rapees', 'Maquereau à la moutarde, purée minute et carottes râpées', 'Des filets de maquereau en conserve écrasés à la moutarde, posés sur une purée minute, avec des carottes râpées citronnées. Riche en oméga-3, zéro cuisson du poisson.', 'À manger tout de suite.', 2, 6, 4, array['plat', 'flemme', 'express', 'peu-de-vaisselle']::text[]),
  ('puree-minute-poisson-blanc-petits-pois-carottes', 'Poisson blanc, purée aux herbes et petits pois-carottes', 'Des filets de poisson blanc cuits encore surgelés, une purée minute aux herbes et des petits pois-carottes. Le dîner doux des soirs sans énergie.', 'Se garde 1 jour au réfrigérateur ; réchauffer doucement à couvert.', 2, 2, 13, array['plat', 'poele', 'flemme', 'express']::text[]),
  ('riz-minute-poulet-curry-petits-pois-carottes', 'Riz poêlé au poulet, petits pois-carottes et curry', 'Du riz cuit en sachet sauté avec du poulet déjà cuit et des petits pois-carottes surgelés, relevé de curry. Une poêle, dix minutes.', 'Se garde 2 jours au réfrigérateur ; bien réchauffer le riz.', 2, 2, 10, array['plat', 'poele', 'flemme', 'express', 'peu-de-vaisselle', 'lunch-box']::text[]),
  ('bol-riz-maquereau-concombre-sesame', 'Bol de riz, maquereau, concombre et sésame', 'Un bol tiède : riz en sachet, maquereau émietté à la sauce soja, concombre croquant et carottes râpées, parsemé de sésame. Aucune cuisson à surveiller.', 'Se garde 1 jour au réfrigérateur, à manger froid ou tiède.', 2, 8, 2, array['plat', 'flemme', 'express', 'monde', 'lunch-box']::text[]),
  ('boeuf-hache-soja-haricots-verts-riz', 'Bœuf haché au soja et au gingembre, haricots verts et riz', 'Du bœuf haché saisi à l''ail et au gingembre, laqué de sauce soja, avec des haricots verts surgelés et du riz en sachet.', 'Se garde 2 jours au réfrigérateur.', 2, 3, 11, array['plat', 'poele', 'monde', 'flemme', 'express']::text[]),
  ('steak-hache-pdt-vapeur-poelee-legumes', 'Steak haché, pommes de terre dorées et poêlée de légumes', 'Des pommes de terre déjà cuites sous vide, juste dorées à la poêle, un steak haché et un mélange de légumes surgelés. Tout se fait en même temps.', 'À manger tout de suite.', 2, 2, 12, array['plat', 'poele', 'flemme', 'express']::text[]),
  ('salade-tiede-poulet-pdt-haricots-verts', 'Salade tiède de poulet, pommes de terre et haricots verts', 'Des pommes de terre vapeur et des haricots verts encore tièdes, du poulet cuit et une vinaigrette à la moutarde. Un plat complet qui se mange aussi froid le lendemain.', 'Se garde 2 jours au réfrigérateur.', 2, 6, 8, array['plat', 'flemme', 'express', 'lunch-box']::text[]),
  ('pdt-vapeur-maquereau-concombre-fromage-blanc', 'Pommes de terre, maquereau et concombre au fromage blanc', 'Des pommes de terre vapeur tièdes, des filets de maquereau et un concombre en sauce fromage blanc ciboulette. Frais, nourrissant, sans allumer le four.', 'Se garde 1 jour au réfrigérateur.', 2, 8, 3, array['plat', 'flemme', 'express', 'peu-de-vaisselle']::text[]),
  ('pates-fraiches-poulet-epinards-fromage-blanc', 'Pâtes fraîches, poulet et épinards crémeux', 'Des pâtes fraîches cuites en trois minutes, du poulet cuit et des épinards surgelés liés au fromage blanc et au parmesan. Crémeux sans crème.', 'Se garde 1 jour au réfrigérateur.', 2, 2, 10, array['plat', 'flemme', 'express']::text[]),
  ('tagliatelles-fraiches-thon-tomates-cerises', 'Tagliatelles fraîches au thon et tomates cerises', 'Des tomates cerises éclatées à la poêle avec de l''ail, du thon émietté et des tagliatelles fraîches. Un plat de placard qui a l''air d''avoir demandé du temps.', 'Se garde 1 jour au réfrigérateur.', 2, 3, 7, array['plat', 'poele', 'flemme', 'express']::text[]),
  ('pates-fraiches-saumon-fume-petits-pois', 'Pâtes fraîches au saumon fumé et petits pois', 'Des pâtes fraîches enrobées d''une sauce légère à la crème et au citron, avec des petits pois surgelés et des lanières de saumon fumé.', 'À manger tout de suite.', 2, 3, 7, array['plat', 'flemme', 'express']::text[]),
  ('raviolis-fromage-petits-pois-jambon', 'Raviolis au fromage, petits pois et jambon', 'Des raviolis frais au fromage, des petits pois surgelés et des lanières de jambon, juste liés au beurre. Un plat d''enfance revisité en sept minutes.', 'Se garde 1 jour au réfrigérateur.', 2, 3, 6, array['plat', 'flemme', 'express', 'peu-de-vaisselle']::text[]),
  ('raviolis-poeles-epinards-ail-oeuf', 'Raviolis poêlés aux épinards et œuf au plat', 'Des raviolis au fromage dorés à la poêle, sur un lit d''épinards à l''ail, avec un œuf au plat. Croustillant dessous, fondant dedans.', 'À manger tout de suite.', 2, 2, 12, array['plat', 'poele', 'flemme', 'express']::text[]),
  ('boulettes-vegetales-tomate-haricots-verts-semoule', 'Boulettes végétales à la tomate, haricots verts et semoule', 'Des boulettes au soja du rayon frais, mijotées quelques minutes dans un coulis de tomate aux herbes, avec des haricots verts et une semoule minute.', 'Se garde 2 jours au réfrigérateur.', 2, 2, 12, array['plat', 'flemme', 'express']::text[]),
  ('boulettes-vegetales-wok-legumes-riz', 'Boulettes végétales sautées au wok de légumes', 'Des boulettes au soja du rayon frais, dorées puis sautées avec un wok de légumes surgelé et du riz en sachet, laquées d''un trait de sauce soja.', 'Se garde 2 jours au réfrigérateur.', 2, 2, 10, array['plat', 'poele', 'monde', 'flemme', 'express']::text[]),
  ('wraps-poulet-carottes-fromage-frais-herbes', 'Wraps de poulet, carottes râpées et sauce aux herbes', 'Des tortillas garnies de poulet cuit, de carottes râpées, de salade et d''une sauce fromage blanc aux herbes. Se roulent en cinq minutes, s''emportent partout.', 'Se garde 1 jour au réfrigérateur, bien filmé.', 2, 8, 0, array['plat', 'flemme', 'express', 'lunch-box', 'peu-de-vaisselle']::text[]),
  ('dinde-paprika-ratatouille-semoule', 'Dinde au paprika, ratatouille minute et semoule', 'Des lanières de dinde poêlées au paprika et une ratatouille de légumes surgelés, servies sur une semoule. Tout le soleil sans éplucher un légume.', 'Se garde 2 jours au réfrigérateur.', 2, 3, 12, array['plat', 'poele', 'flemme', 'express', 'lunch-box']::text[]),
  ('gnocchi-poeles-poulet-ratatouille', 'Gnocchis poêlés, poulet et ratatouille', 'Des gnocchis dorés directement à la poêle, sans les cuire à l''eau, avec une ratatouille surgelée et du poulet cuit. Une seule poêle, un dîner complet.', 'Se garde 1 jour au réfrigérateur.', 2, 2, 12, array['plat', 'poele', 'flemme', 'express', 'peu-de-vaisselle']::text[])
) as v(slug, title, description, storage, servings, prep, cook, tags);

