insert into public.recipe_steps (recipe_id, position, instruction)
select r.id, v.pos, v.instruction
from (values
  ('puree-minute-ail-steak-hache-haricots-verts', 1, 'Cuire les haricots verts surgelés 8 à 10 minutes dans l''eau bouillante salée, puis les égoutter.'),
  ('puree-minute-ail-steak-hache-haricots-verts', 2, 'Porter le lait, l''eau et l''ail écrasé à frémissement, retirer du feu et verser les flocons en remuant à la fourchette jusqu''à une purée lisse ; ajouter le beurre.'),
  ('puree-minute-ail-steak-hache-haricots-verts', 3, 'Saisir les steaks dans une poêle chaude huilée, 2 à 3 minutes de chaque côté selon la cuisson voulue.'),
  ('puree-minute-ail-steak-hache-haricots-verts', 4, 'Servir le steak salé et poivré avec la purée et les haricots verts persillés.'),
  ('puree-verte-epinards-oeufs-mollets', 1, 'Cuire les épinards surgelés à couvert dans une casserole avec un fond d''eau, 8 minutes à feu moyen, puis bien les égoutter.'),
  ('puree-verte-epinards-oeufs-mollets', 2, 'Plonger les œufs dans l''eau bouillante 6 minutes, les rafraîchir à l''eau froide et les écaler.'),
  ('puree-verte-epinards-oeufs-mollets', 3, 'Porter le lait et l''eau à frémissement, retirer du feu, verser les flocons puis incorporer les épinards, la muscade et l''emmental.'),
  ('puree-verte-epinards-oeufs-mollets', 4, 'Servir la purée verte avec les œufs mollets coupés en deux, salés et poivrés.'),
  ('dinde-moutarde-petits-pois-carottes-puree', 1, 'Cuire les petits pois-carottes surgelés 10 minutes à couvert dans une casserole avec un fond d''eau salée.'),
  ('dinde-moutarde-petits-pois-carottes-puree', 2, 'Dorer les escalopes dans une poêle huilée à feu moyen, 3 à 4 minutes de chaque côté.'),
  ('dinde-moutarde-petits-pois-carottes-puree', 3, 'Déglacer la poêle avec un trait d''eau et la moutarde, et laisser napper 1 minute en retournant la dinde.'),
  ('dinde-moutarde-petits-pois-carottes-puree', 4, 'Porter le lait et l''eau à frémissement, retirer du feu, verser les flocons et mélanger ; servir le tout ensemble.'),
  ('maquereau-moutarde-puree-carottes-rapees', 1, 'Égoutter les maquereaux et les écraser grossièrement à la fourchette avec la moutarde.'),
  ('maquereau-moutarde-puree-carottes-rapees', 2, 'Assaisonner les carottes râpées avec l''huile, le jus de citron, du sel et du poivre.'),
  ('maquereau-moutarde-puree-carottes-rapees', 3, 'Porter le lait et l''eau à frémissement, retirer du feu, verser les flocons et mélanger.'),
  ('maquereau-moutarde-puree-carottes-rapees', 4, 'Servir la purée surmontée du maquereau et de ciboulette, avec les carottes râpées.'),
  ('puree-minute-poisson-blanc-petits-pois-carottes', 1, 'Cuire les petits pois-carottes surgelés 10 minutes à couvert dans une casserole avec un fond d''eau salée.'),
  ('puree-minute-poisson-blanc-petits-pois-carottes', 2, 'Poser les filets encore surgelés dans une poêle huilée, couvrir et cuire 10 à 12 minutes à feu moyen en les retournant à mi-cuisson : la chair doit s''effeuiller.'),
  ('puree-minute-poisson-blanc-petits-pois-carottes', 3, 'Porter le lait et l''eau à frémissement, retirer du feu, verser les flocons puis les herbes ciselées.'),
  ('puree-minute-poisson-blanc-petits-pois-carottes', 4, 'Servir le poisson arrosé de jus de citron, avec la purée et les légumes.'),
  ('riz-minute-poulet-curry-petits-pois-carottes', 1, 'Faire revenir les petits pois-carottes surgelés dans la poêle huilée à feu vif, 5 à 6 minutes, jusqu''à ce qu''ils soient tendres.'),
  ('riz-minute-poulet-curry-petits-pois-carottes', 2, 'Ajouter le poulet et le curry, puis sauter 2 minutes.'),
  ('riz-minute-poulet-curry-petits-pois-carottes', 3, 'Ajouter le riz égrené et la sauce soja, puis poêler 2 à 3 minutes en remuant jusqu''à ce qu''il soit chaud.'),
  ('riz-minute-poulet-curry-petits-pois-carottes', 4, 'Servir parsemé de coriandre.'),
  ('bol-riz-maquereau-concombre-sesame', 1, 'Réchauffer le riz en sachet selon le paquet, 2 minutes.'),
  ('bol-riz-maquereau-concombre-sesame', 2, 'Couper le concombre en demi-rondelles et le mélanger aux carottes râpées avec le vinaigre.'),
  ('bol-riz-maquereau-concombre-sesame', 3, 'Émietter le maquereau égoutté avec la sauce soja et l''huile de sésame.'),
  ('bol-riz-maquereau-concombre-sesame', 4, 'Répartir le riz dans les bols, ajouter les légumes et le maquereau, puis parsemer de sésame.'),
  ('boeuf-hache-soja-haricots-verts-riz', 1, 'Cuire les haricots verts surgelés 8 minutes dans l''eau bouillante salée, puis les égoutter.'),
  ('boeuf-hache-soja-haricots-verts-riz', 2, 'Saisir le bœuf haché dans la poêle huilée à feu vif avec l''ail et le gingembre, 4 à 5 minutes en l''émiettant, jusqu''à ce qu''il soit bien doré.'),
  ('boeuf-hache-soja-haricots-verts-riz', 3, 'Ajouter les haricots verts et la sauce soja, puis sauter 2 minutes.'),
  ('boeuf-hache-soja-haricots-verts-riz', 4, 'Réchauffer le riz selon le paquet et servir avec le bœuf, relevé de piment.'),
  ('steak-hache-pdt-vapeur-poelee-legumes', 1, 'Couper les pommes de terre en deux et les dorer dans une poêle huilée à feu vif, 8 à 10 minutes en les retournant.'),
  ('steak-hache-pdt-vapeur-poelee-legumes', 2, 'Dans une autre poêle huilée, faire revenir les légumes surgelés à feu vif 6 à 8 minutes, avec les herbes.'),
  ('steak-hache-pdt-vapeur-poelee-legumes', 3, 'Pousser les légumes sur le côté et saisir les steaks 2 à 3 minutes de chaque côté.'),
  ('steak-hache-pdt-vapeur-poelee-legumes', 4, 'Servir salé et poivré.'),
  ('salade-tiede-poulet-pdt-haricots-verts', 1, 'Cuire les haricots verts surgelés 8 minutes dans l''eau bouillante salée, en ajoutant les pommes de terre coupées en morceaux pour les 2 dernières minutes, puis égoutter.'),
  ('salade-tiede-poulet-pdt-haricots-verts', 2, 'Mélanger l''huile, le vinaigre, la moutarde et l''échalote ciselée.'),
  ('salade-tiede-poulet-pdt-haricots-verts', 3, 'Couper le poulet en lamelles.'),
  ('salade-tiede-poulet-pdt-haricots-verts', 4, 'Mélanger le tout encore tiède avec la vinaigrette et le persil.'),
  ('pdt-vapeur-maquereau-concombre-fromage-blanc', 1, 'Réchauffer les pommes de terre selon le paquet, 2 à 3 minutes, puis les couper en rondelles.'),
  ('pdt-vapeur-maquereau-concombre-fromage-blanc', 2, 'Couper le concombre en dés et le mélanger au fromage blanc, à la ciboulette, au jus de citron, au sel et au poivre.'),
  ('pdt-vapeur-maquereau-concombre-fromage-blanc', 3, 'Égoutter le maquereau et le détailler en morceaux.'),
  ('pdt-vapeur-maquereau-concombre-fromage-blanc', 4, 'Servir les pommes de terre avec le maquereau et le concombre au fromage blanc.'),
  ('pates-fraiches-poulet-epinards-fromage-blanc', 1, 'Cuire les épinards surgelés à couvert dans une sauteuse avec l''ail écrasé et un fond d''eau, 7 à 8 minutes à feu moyen.'),
  ('pates-fraiches-poulet-epinards-fromage-blanc', 2, 'Cuire les pâtes fraîches 2 à 3 minutes dans l''eau bouillante salée, puis les égoutter en gardant un peu d''eau de cuisson.'),
  ('pates-fraiches-poulet-epinards-fromage-blanc', 3, 'Ajouter aux épinards le poulet en lamelles, le fromage blanc et la muscade, puis réchauffer 1 minute sans faire bouillir.'),
  ('pates-fraiches-poulet-epinards-fromage-blanc', 4, 'Mélanger avec les pâtes et un trait d''eau de cuisson, puis servir avec le parmesan.'),
  ('tagliatelles-fraiches-thon-tomates-cerises', 1, 'Faire revenir les tomates cerises entières et l''ail écrasé dans la poêle huilée à feu vif, 5 minutes, jusqu''à ce qu''elles éclatent.'),
  ('tagliatelles-fraiches-thon-tomates-cerises', 2, 'Cuire les pâtes fraîches 2 à 3 minutes dans l''eau bouillante salée, puis les égoutter en gardant un peu d''eau de cuisson.'),
  ('tagliatelles-fraiches-thon-tomates-cerises', 3, 'Ajouter le thon émietté aux tomates, puis les pâtes et un trait d''eau de cuisson, et mélanger 1 minute.'),
  ('tagliatelles-fraiches-thon-tomates-cerises', 4, 'Servir avec le basilic et le parmesan.'),
  ('pates-fraiches-saumon-fume-petits-pois', 1, 'Cuire les petits pois surgelés 4 minutes dans l''eau bouillante salée, ajouter les pâtes fraîches et cuire encore 2 à 3 minutes, puis égoutter.'),
  ('pates-fraiches-saumon-fume-petits-pois', 2, 'Chauffer la crème avec le jus de citron dans la casserole vide, 1 minute.'),
  ('pates-fraiches-saumon-fume-petits-pois', 3, 'Remettre les pâtes et les petits pois, puis ajouter le saumon en lanières hors du feu.'),
  ('pates-fraiches-saumon-fume-petits-pois', 4, 'Servir avec la ciboulette et du poivre.'),
  ('raviolis-fromage-petits-pois-jambon', 1, 'Cuire les petits pois surgelés 3 minutes dans l''eau bouillante salée.'),
  ('raviolis-fromage-petits-pois-jambon', 2, 'Ajouter les raviolis et cuire 2 à 3 minutes, jusqu''à ce qu''ils remontent, puis égoutter.'),
  ('raviolis-fromage-petits-pois-jambon', 3, 'Remettre dans la casserole avec le beurre et le jambon en lanières, et mélanger hors du feu.'),
  ('raviolis-fromage-petits-pois-jambon', 4, 'Servir poivré, avec le parmesan.'),
  ('raviolis-poeles-epinards-ail-oeuf', 1, 'Cuire les épinards surgelés à couvert dans une casserole avec l''ail écrasé et un fond d''eau, 8 minutes à feu moyen.'),
  ('raviolis-poeles-epinards-ail-oeuf', 2, 'Dorer les raviolis crus dans une poêle huilée à feu moyen, 3 minutes, puis ajouter un fond d''eau et couvrir 2 minutes.'),
  ('raviolis-poeles-epinards-ail-oeuf', 3, 'Casser les œufs dans la poêle à côté des raviolis et cuire 3 minutes, jusqu''à ce que le blanc soit pris.'),
  ('raviolis-poeles-epinards-ail-oeuf', 4, 'Servir les raviolis et l''œuf sur les épinards, avec du piment.'),
  ('boulettes-vegetales-tomate-haricots-verts-semoule', 1, 'Cuire les haricots verts surgelés 8 à 10 minutes dans l''eau bouillante salée, puis les égoutter.'),
  ('boulettes-vegetales-tomate-haricots-verts-semoule', 2, 'Dorer les boulettes dans une sauteuse huilée, 3 minutes, puis ajouter le coulis et les herbes et laisser mijoter 6 minutes à couvert.'),
  ('boulettes-vegetales-tomate-haricots-verts-semoule', 3, 'Verser la semoule dans un bol, la couvrir d''eau bouillante salée à hauteur, couvrir 5 minutes puis l''égrener.'),
  ('boulettes-vegetales-tomate-haricots-verts-semoule', 4, 'Servir les boulettes en sauce avec la semoule et les haricots verts.'),
  ('boulettes-vegetales-wok-legumes-riz', 1, 'Dorer les boulettes dans le wok huilé à feu moyen, 3 à 4 minutes en les roulant.'),
  ('boulettes-vegetales-wok-legumes-riz', 2, 'Ajouter les légumes surgelés et le gingembre, puis sauter 5 minutes à feu vif.'),
  ('boulettes-vegetales-wok-legumes-riz', 3, 'Ajouter le riz égrené et la sauce soja, puis sauter 2 minutes.'),
  ('boulettes-vegetales-wok-legumes-riz', 4, 'Servir avec du piment.'),
  ('wraps-poulet-carottes-fromage-frais-herbes', 1, 'Mélanger le fromage blanc avec les herbes ciselées, du sel et du poivre.'),
  ('wraps-poulet-carottes-fromage-frais-herbes', 2, 'Couper le poulet en lamelles et effeuiller la salade.'),
  ('wraps-poulet-carottes-fromage-frais-herbes', 3, 'Tartiner les tortillas de sauce, puis garnir de poulet, de carottes râpées et de salade.'),
  ('wraps-poulet-carottes-fromage-frais-herbes', 4, 'Rouler serré et couper en deux.'),
  ('dinde-paprika-ratatouille-semoule', 1, 'Faire revenir les légumes surgelés et l''ail dans une sauteuse huilée à feu vif, 10 minutes, jusqu''à ce que l''eau soit évaporée.'),
  ('dinde-paprika-ratatouille-semoule', 2, 'Couper la dinde en lanières et la dorer au paprika dans une poêle huilée, 5 à 6 minutes.'),
  ('dinde-paprika-ratatouille-semoule', 3, 'Verser la semoule dans un bol, la couvrir d''eau bouillante salée à hauteur, couvrir 5 minutes puis l''égrener.'),
  ('dinde-paprika-ratatouille-semoule', 4, 'Servir la dinde et la ratatouille sur la semoule.'),
  ('gnocchi-poeles-poulet-ratatouille', 1, 'Dorer les gnocchis dans une grande poêle huilée à feu moyen, 5 à 6 minutes en remuant.'),
  ('gnocchi-poeles-poulet-ratatouille', 2, 'Ajouter les légumes surgelés et cuire 6 minutes à feu vif, jusqu''à ce que l''eau soit évaporée.'),
  ('gnocchi-poeles-poulet-ratatouille', 3, 'Ajouter le poulet en lamelles et réchauffer 1 minute.'),
  ('gnocchi-poeles-poulet-ratatouille', 4, 'Servir avec le parmesan et le basilic.')
) as v(recipe, pos, instruction)
join public.recipes r on r.slug = v.recipe;

-- Garde-fou : une jointure silencieusement vide (slug introuvable) fait échouer la migration.
do $$
begin
  if (select count(*) from public.recipe_ingredients ri join public.recipes r on r.id = ri.recipe_id
      where r.slug in ('puree-minute-ail-steak-hache-haricots-verts', 'puree-verte-epinards-oeufs-mollets', 'dinde-moutarde-petits-pois-carottes-puree', 'maquereau-moutarde-puree-carottes-rapees', 'puree-minute-poisson-blanc-petits-pois-carottes', 'riz-minute-poulet-curry-petits-pois-carottes', 'bol-riz-maquereau-concombre-sesame', 'boeuf-hache-soja-haricots-verts-riz', 'steak-hache-pdt-vapeur-poelee-legumes', 'salade-tiede-poulet-pdt-haricots-verts', 'pdt-vapeur-maquereau-concombre-fromage-blanc', 'pates-fraiches-poulet-epinards-fromage-blanc', 'tagliatelles-fraiches-thon-tomates-cerises', 'pates-fraiches-saumon-fume-petits-pois', 'raviolis-fromage-petits-pois-jambon', 'raviolis-poeles-epinards-ail-oeuf', 'boulettes-vegetales-tomate-haricots-verts-semoule', 'boulettes-vegetales-wok-legumes-riz', 'wraps-poulet-carottes-fromage-frais-herbes', 'dinde-paprika-ratatouille-semoule', 'gnocchi-poeles-poulet-ratatouille')) <> 173 then
    raise exception 'Lignes d''ingrédients manquantes dans le vingt-cinquième lot de recettes.';
  end if;
end;
$$;
